ValidationRule.errorConditionFormula:
AND(
    /* Exclude Record Types */
    NOT(
    OR(
       RecordType.DeveloperName = "DairyWorkerLicence",
       RecordType.DeveloperName = "PHOCSBCCDCDairyPlantLicence"
      )
      ),
    NOT(ISBLANK(AccountId)),
    NOT(ISBLANK(LicenseTypeId)),

    TEXT(Account.Type) = "Tobacco and Vapour",

    NOT(
        AND(
            Account.RecordTypeName__c = "Facility",
            OR(
                RecordType.DeveloperName = "OperatingPermitApplication",
                RecordType.DeveloperName = "PHOCSExemptions"
            ),
            LicenseType.Name = "Tobacco and Vapour Retailer Information"
        )
    )
)
